import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.Bqa2y7hU.js";const u=JSON.parse('{"title":"控制台总览","description":"控制台六个模块各自管什么，以及第一次上手的五步流程。","frontmatter":{"title":"控制台总览","description":"控制台六个模块各自管什么，以及第一次上手的五步流程。"},"headers":[],"relativePath":"console/overview.md","filePath":"console/overview.md","lastUpdated":1789292506000}'),d={name:"console/overview.md"};function l(i,t,h,s,n,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="控制台总览-🔧" tabindex="-1">控制台总览 🔧 <a class="header-anchor" href="#控制台总览-🔧" aria-label="Permalink to &quot;控制台总览 🔧&quot;">​</a></h1><p>控制台是你日常使用 Xiaoyi_QQ_V4 的主界面：建机器人、装插件、看日志、查账单、生成 API Key 都在这里完成，不用登服务器。</p><p>这页给你一张地图——六个模块各管什么，以及从零到「机器人在群里回话」的最短路径。</p><h2 id="_1-六个模块" tabindex="-1">1. 六个模块 <a class="header-anchor" href="#_1-六个模块" aria-label="Permalink to &quot;1. 六个模块&quot;">​</a></h2><p>登录后左侧是导航，一共六块：</p><table tabindex="0"><thead><tr><th>模块</th><th>管什么</th><th>什么时候会用到</th></tr></thead><tbody><tr><td>仪表盘</td><td>概览：机器人数量、在线情况、服务器负载等</td><td>每天进来先看一眼</td></tr><tr><td>我的机器人</td><td>添加 / 查看机器人，进详情页管插件、看数据与日志</td><td>接入机器人、排障</td></tr><tr><td>插件市场</td><td>浏览插件、装到某台机器人、启停与调优先级</td><td>给机器人加功能</td></tr><tr><td>订阅中心</td><td>套餐、余额、卡密兑换、充值</td><td>额度不够、到期续费</td></tr><tr><td>用户中心</td><td>账号资料、通知、开放 API 的 Key</td><td>生成 API Key、看账单通知</td></tr><tr><td>开放 API</td><td>用程序调用框架能力</td><td>做二次开发、对接自有系统</td></tr></tbody></table><p>「开放 API」这块的具体接口清单见 <a href="/RuaBot.Doc/console/openapi">开放 API</a>。</p><details class="details custom-block"><summary>截图占位</summary><p>截控制台首页，左侧导航展开的状态，六个模块名称都要露出。</p></details><h2 id="_2-第一次上手-五步" tabindex="-1">2. 第一次上手：五步 <a class="header-anchor" href="#_2-第一次上手-五步" aria-label="Permalink to &quot;2. 第一次上手：五步&quot;">​</a></h2><h3 id="第-1-步-打开控制台并登录" tabindex="-1">第 1 步：打开控制台并登录 <a class="header-anchor" href="#第-1-步-打开控制台并登录" aria-label="Permalink to &quot;第 1 步：打开控制台并登录&quot;">​</a></h3><p>用服务商给你的访问地址打开页面（默认是服务器的 <code>8080</code> 端口，通常已经套好域名和 HTTPS）。首次使用需要注册账号。</p><h3 id="第-2-步-确认订阅状态" tabindex="-1">第 2 步：确认订阅状态 <a class="header-anchor" href="#第-2-步-确认订阅状态" aria-label="Permalink to &quot;第 2 步：确认订阅状态&quot;">​</a></h3><p>账号注册好之后，先去「订阅中心」看当前套餐。<strong>套餐决定你能建几台机器人、装几个插件</strong>——额度用满是新手最常见的卡点。</p><p>如果服务商给你的是卡密，在这一步兑换，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>。</p><h3 id="第-3-步-添加第一台机器人" tabindex="-1">第 3 步：添加第一台机器人 <a class="header-anchor" href="#第-3-步-添加第一台机器人" aria-label="Permalink to &quot;第 3 步：添加第一台机器人&quot;">​</a></h3><p>进「我的机器人」→「添加机器人」，跟着两步向导走。你需要先准备好机器人的凭据（QQ 官方的 <code>AppID</code> / <code>AppSecret</code>，或一个跑起来的 OneBot 实现端），具体见 <a href="/RuaBot.Doc/platforms/overview">接入方式总览</a>。</p><p>创建后机器人<strong>立即上线</strong>，不需要重启服务。</p><h3 id="第-4-步-装插件" tabindex="-1">第 4 步：装插件 <a class="header-anchor" href="#第-4-步-装插件" aria-label="Permalink to &quot;第 4 步：装插件&quot;">​</a></h3><p>进「插件市场」，挑一个插件装到刚建的机器人上，然后启用。装完可以打开插件自带的 Web 面板做配置，见 <a href="/RuaBot.Doc/console/plugins">插件市场与安装</a>。</p><h3 id="第-5-步-验证" tabindex="-1">第 5 步：验证 <a class="header-anchor" href="#第-5-步-验证" aria-label="Permalink to &quot;第 5 步：验证&quot;">​</a></h3><p>到机器人详情页看「日志」Tab 有没有正常运行输出；在群里发条消息，看「数据」Tab 里有没有消息记录。</p><p>到这一步，一个能用的机器人就跑起来了。后面的「用户中心 → 开放 API」只有在你需要用程序调用时才要配。</p><h2 id="_3-关于注册限制" tabindex="-1">3. 关于注册限制 <a class="header-anchor" href="#_3-关于注册限制" aria-label="Permalink to &quot;3. 关于注册限制&quot;">​</a></h2><p>服务商可以开启注册限制。如果你看到的是受限的注册页，通常会遇到这些要求：</p><table tabindex="0"><thead><tr><th>你会看到</th><th>说明</th></tr></thead><tbody><tr><td>注册需要填 QQ 号</td><td>用真实可联系的 QQ 号，后续找服务商处理问题时会用到</td></tr><tr><td>可能需要邮箱验证</td><td>按页面提示去邮箱点验证链接</td></tr></tbody></table><p>如果注册被拒绝、或者填完提示不允许注册，说明服务商当前关闭了自助注册，需要直接联系服务商开通账号。</p><div class="warning custom-block"><p class="custom-block-title">找服务商，不要自己想办法绕</p><p>注册限制、额度、授权这些都由服务商控制，页面上没有开关。遇到问题请联系服务商，不要尝试改配置或数据库。</p></div><h2 id="_4-几个通用约定" tabindex="-1">4. 几个通用约定 <a class="header-anchor" href="#_4-几个通用约定" aria-label="Permalink to &quot;4. 几个通用约定&quot;">​</a></h2><ul><li>页面上的操作<strong>即时生效</strong>，不需要重启服务；只有换端口、换数据库连接这类部署级配置才需要重启</li><li>机器人的运行日志在它自己的详情页里，不用去服务器上翻</li><li>插件的数据和配置是<strong>按机器人维度</strong>存的——同一插件装到两台机器人上，是两份独立配置</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a></li><li><a href="/RuaBot.Doc/platforms/overview">接入方式总览</a></li></ul>',31)])])}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
